def parse_cron_field(field: str, min_val: int, max_val: int) -> list:
    result = set()

    for part in field.split(','):
        step = 1
        if '/' in part:
            range_part, step_str = part.split('/', 1)
            step = int(step_str)
        else:
            range_part = part

        if range_part == '*':
            start, end = min_val, max_val
        elif '-' in range_part:
            start_str, end_str = range_part.split('-', 1)
            start, end = int(start_str), int(end_str)
        else:
            start = end = int(range_part)

        for i in range(start, end + 1):
            if (i - start) % step == 0:
                if min_val <= i <= max_val:
                    result.add(i)

    return sorted(result)

def matches_cron(expression: str, dt) -> bool:
    fields = expression.strip().split()
    if len(fields) != 5:
        return False

    minute_match = dt['minute'] in parse_cron_field(fields[0], 0, 59)
    hour_match = dt['hour'] in parse_cron_field(fields[1], 0, 23)
    day_match = dt['day'] in parse_cron_field(fields[2], 1, 31)
    month_match = dt['month'] in parse_cron_field(fields[3], 1, 12)
    weekday_match = dt['weekday'] in parse_cron_field(fields[4], 0, 6)

    return minute_match and hour_match and day_match and month_match and weekday_match

