function parseCronField(field, min, max) {
  const result = new Set();

  for (const part of field.split(',')) {
    let step = 1;
    let rangePart = part;

    if (part.includes('/')) {
      [rangePart, step] = part.split('/');
      step = parseInt(step);
    }

    let start, end;
    if (rangePart === '*') {
      start = min;
      end = max;
    } else if (rangePart.includes('-')) {
      [start, end] = rangePart.split('-').map(Number);
    } else {
      start = end = parseInt(rangePart);
    }

    for (let i = start; i <= end; i++) {
      if ((i - start) % step === 0 && i >= min && i <= max) {
        result.add(i);
      }
    }
  }

  return [...result].sort((a, b) => a - b);
}

function matchesCron(expression, date) {
  const fields = expression.trim().split(/\s+/);
  if (fields.length !== 5) return false;

  const minute = typeof date === 'object' ? date.minute : date.getMinutes();
  const hour = typeof date === 'object' ? date.hour : date.getHours();
  const day = typeof date === 'object' ? date.day : date.getDate();
  const month = typeof date === 'object' ? date.month : date.getMonth() + 1;
  const weekday = typeof date === 'object' ? date.weekday : date.getDay();

  return parseCronField(fields[0], 0, 59).includes(minute) &&
    parseCronField(fields[1], 0, 23).includes(hour) &&
    parseCronField(fields[2], 1, 31).includes(day) &&
    parseCronField(fields[3], 1, 12).includes(month) &&
    parseCronField(fields[4], 0, 6).includes(weekday);
}
